Using groucho-fp (with @ngwes/mini-fp), rewrite this function as a pipeline of stages. Give the context type, the error type, every stage, and the initial context built from the input.

```ts
async function processOrder(input: { orderId: string; couponCode?: string }) {
  const order = await db.findOrder(input.orderId);
  if (!order) throw new Error('order not found');
  if (order.lines.length === 0) throw new Error('empty order');
  const subtotal = order.lines.reduce((sum, l) => sum + l.price * l.quantity, 0);
  const discount = input.couponCode ? await coupons.discountFor(input.couponCode) : 0;
  const total = Math.max(0, subtotal - discount);
  await payments.charge(order.customerId, total);
  return { orderId: input.orderId, total };
}
```

A missing order and an empty order are expected failures, not crashes.

Using groucho-fp, this pipeline stops with a conflict error and never produces tokens. Fix the stages so that the run completes with the trimmed, lowercased text, its tokens and the metadata. The stages run in this order, over the initial context `{ raw, meta: { source: 'api' } }`:

```ts
type Meta = { source: string; lang?: string };
type Ctx = { raw: string; meta: Meta; text?: string; tokens?: string[] };
type Err = { tag: 'empty' } | { tag: 'crash'; cause: unknown } | { tag: 'conflict'; keys: ReadonlyArray<string> };

const clean: Step<Err, Ctx> = (ctx) => right({ ...ctx, text: ctx.raw.trim() });
const lower: Step<Err, Ctx> = (ctx) => right({ ...ctx, text: (ctx.text ?? '').toLowerCase() });
const withDefaults: Step<Err, Ctx> = (ctx) => right({ ...ctx, meta: { lang: 'en', ...ctx.meta } });
const tokenize: Step<Err, Ctx> = (ctx) => {
  const { raw, ...rest } = ctx;
  return right({ ...rest, tokens: (ctx.text ?? '').split(/\s+/) } as Ctx);
};
```
